using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public class MyResources
{
    [McpServerResource(UriTemplate = "config://app", Name = "AppConfig",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://features", Name = "FeatureFlags",
        MimeType = "application/json")]
    public static string GetFeatureFlags()
    {
        var flags = new
        {
            EnableCaching = true,
            EnableDetailedLogs = false,
            MaxConcurrentRequests = 100
        };

        return JsonSerializer.Serialize(flags, new JsonSerializerOptions { WriteIndented = true });
    }
}

